local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule

------------ import ------------
local URPBaseCamera = CS.Game.Native.URP.URPBaseCamera
local PinchAndDragInputModule = CS.Engine.UI.PinchAndDragInputModule
---@type Engine.UI.UIRaycastBlocker
local blockerInstance = CS.Engine.UI.UIRaycastBlocker.Instance
local cs_coroutine = require('XLua.cs_coroutine')

------------ import ------------

------------ define ------------
local CatModelInteractionLocalRotation = {
    Child = Quaternion.Euler(0, -171, 0),
    Adult = Quaternion.Euler(0, -145, 0)
}
local shadowVerticalOffset = 0.034 -- 原始值为 0.034
---@type MaidCoffeeConstants
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
------------ define ------------

--- from: 
---@class MaidCoffeeCatDrawPreviewDialog
---@field Env                           	MaidCoffeeCatDrawPreviewDialog          
---@field controller                    	Engine.UI.UILuaDialog                   
---@field TextTitle3                    	UnityEngine.RectTransform               
---@field TextTitle2                    	UnityEngine.RectTransform               
---@field TextTitle1                    	UnityEngine.RectTransform               
---@field OverseaManageCatballSkillDescNode	UnityEngine.RectTransform               
---@field ImgNew                        	UnityEngine.RectTransform               
---@field TextName                      	UnityEngine.UI.Text                     
---@field TouchRegion                   	UnityEngine.RectTransform               
local MaidCoffeeCatDrawPreviewDialog = Class("MaidCoffeeCatDrawPreviewDialog")

function MaidCoffeeCatDrawPreviewDialog:__init()
    self.cats = nil
    self.catGo = nil
    self.curDojo = nil
    self.curIndex = 1
    self.isFinish = false
    self.cb = nil
end

function MaidCoffeeCatDrawPreviewDialog:__delete()
    self.cats = nil
    self.controller = nil
    self.catGo = nil
    self.curDojo = nil
    self.curIndex = 1
    self.cb = nil
    self.isFinish = false
end

function MaidCoffeeCatDrawPreviewDialog:Awake()
    CfUtils.SetTopCommonActive(false, false)
    local initParams = self.controller.Argument.parameters
    self.cats = initParams.cats
    print('--->>>', table.dump(self.cats, false, 2))
    self.cb = initParams.cb
    --if Config.DEBUG then
    --    ---@type CatEggComponent
    --    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    --    local cats = table.values(eggComponent.cats)
    --    self.cats = cats
    --end
    ---@type Engine.UI.PinchAndDragInputModule
    local inputModule = self.TouchRegion.gameObject:EnsureComponent(typeof(PinchAndDragInputModule))
    inputModule.onSingleFingerUp:AddListener(function(position)
        if isNull(position) then
            return
        end
        ---单点事件
        print('----->>点击事件', self.curIndex, #self.cats, self.isFinish)
        if self.curIndex <= #self.cats and self.isFinish then
            ---加载下一个猫球
            cs_coroutine.start(function()
                cs_coroutine.yield_return(self:LoadCatModelAsync())
            end)
        elseif self.curIndex > #self.cats then
            ---结果结束，关闭当前页面，回调
            UIModule.CloseDialog(self.controller)
            if self.cb then
                self.cb()
            end
        end
    end)
    local abs = math.abs
    inputModule.onSingleFingerDrag:AddListener(function(delta)
        if isNull(self.catGo) then return end
        local y = delta.y
        local x = delta.x
        if abs(x) < abs(y) then
            return
        end
        local direction = x < 0 and 1 or -1
        local eulerAngles = Vector3.New(0, 1, 0)
        eulerAngles.y = eulerAngles.y * direction * abs(x)
        self.catGo.transform:Rotate(eulerAngles)
    end)
end

---LoadCatModelAsync
function MaidCoffeeCatDrawPreviewDialog:LoadCatModelAsync()
    print('---->>', self.curIndex, #self.cats)
    if self.curIndex <= #self.cats then
        self.isFinish = false
        blockerInstance:AddCondition("LoadCatModelAsync")
        ---@type CatEggDojo
        local catDojo = self.cats[self.curIndex]
        self.curDojo = catDojo
        self.curIndex = self.curIndex + 1
        self:DeleteCatGameObject()
        ---@type MaidCoffeeCatRollConfigVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4000, 'MaidCoffeeCatRollConfigVo', catDojo.catId)
        self:FreshUI(catDojo, vo)
        try(function()
            ---@type CatEggComponent
            local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
            coroutine.yield(eggComponent:LoadCatModelAsync(MaidCoffeeConstants.BornType.Adult, vo.catId, false, catDojo.genes, nil, function(go)
                ---@type UnityEngine.Transform
                go.name = tostring(catDojo.id)
                self.catGo = go
                local trans = go.transform
                trans.position = Vector3.New(-0.03, shadowVerticalOffset, 0)
                trans.localRotation = CatModelInteractionLocalRotation.Adult
                self.isFinish = true
                blockerInstance:RemoveCondition("LoadCatModelAsync")
            end))
        end, function()
            blockerInstance:RemoveCondition("LoadCatModelAsync")
        end)
    end
end

---FreshUI
---刷新ui的显示信息
---@param catDojo CatEggDojo
---@param vo MaidCoffeeCatRollConfigVo
function MaidCoffeeCatDrawPreviewDialog:FreshUI(catDojo, vo)
    KTool.SetActive(self.ImgNew.gameObject, checkBool(catDojo.isNew))
    if checkNumber(vo.quality) == MaidCoffeeConstants.CatBallQuality.Theme then
        KTool.SetActive(self.TextTitle2.gameObject, true)
        KTool.SetActive(self.TextTitle1.gameObject, true)
        KTool.SetActive(self.TextTitle3.gameObject, true)
    else
        KTool.SetActive(self.TextTitle2.gameObject, false)
    end
    self.TextName.text = tostring(vo.name)
    ----@type OverseaManageCatBallSkillDescNode
    local env = CfUtils.GetLuaScr(self.OverseaManageCatballSkillDescNode.gameObject, MaidCoffeeConstants.EnvPath.OverseaManageCatBallSkillDescNode)
    env._selectTag = 1
    env:FreshUI(catDojo, vo)
end

function MaidCoffeeCatDrawPreviewDialog:DeleteCatGameObject()
    if not isNull(self.catGo) then
        KTool.SafeDelete(self.catGo, true)
    end
    self.catGo = nil
end

function MaidCoffeeCatDrawPreviewDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ----列新猫的信息
        coroutine.yield(self:LoadCatModelAsync())
    end))
    return coWait
end

function MaidCoffeeCatDrawPreviewDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---加载场景
        local sceneManagement = SceneManagement:GetInstance()
        coroutine.yield(sceneManagement:AppendScene(Constants.IdSceneSetting24,false))
        coroutine.yield()
        ---@type SceneInstance
        local coffeeSceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting24)
        local cameraObject = coffeeSceneInstance:GetCacheObjectByName("Main Camera")
        ---@type SceneInstance
        local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting46)
        sceneInstance:Disable(false)
        KTool.GetOrAddComponent(cameraObject, typeof(URPBaseCamera))
        coffeeSceneInstance:Enable(true)
    end))
    return coWait
end

function MaidCoffeeCatDrawPreviewDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---加载场景
        local sceneManagement = SceneManagement:GetInstance()
        ---@type SceneInstance
        local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting46)
        ---@type SceneInstance
        local coffeeSceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting24)
        coffeeSceneInstance:Disable(true)
        sceneInstance:Enable(true)
    end))
    return coWait
end

function MaidCoffeeCatDrawPreviewDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---加载场景
        self:DeleteCatGameObject()
        local sceneManagement = SceneManagement:GetInstance()
        coroutine.yield(sceneManagement:UnloadAppendedSceneById(Constants.IdSceneSetting24))
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return MaidCoffeeCatDrawPreviewDialog